import { createApp, defineComponent, h, nextTick, ref, type App } from 'vue'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type { ChatMessage } from '@/store/chat/types'
import { setupApiClient } from '@/lib/api-client'
import { useChatReadAloud } from './useChatReadAloud'
const requests: Request[] = []
const players: Player[] = []
class Player extends EventTarget {
 src = ''
 play = vi.fn(async () => {})
 pause = vi.fn()
 load = vi.fn()
}
let app: App | undefined, root: HTMLDivElement | undefined
const tick = async () => { await nextTick(); for (let i = 0; i < 20; i++) await Promise.resolve(); await nextTick() }
const bot='10000000-0000-4000-8000-000000000001'
const message=(streaming: boolean): Extract<ChatMessage, {role:'assistant'}> => ({id:'reply',turnId:'turn',runtimeRunId:'run',role:'assistant',timestamp:'',streaming,messages:[{id:0,type:'text',content:'手机端合成验证'}]})
function audioResponse() {
 const response=new Response('synthetic audio',{status:200,headers:{'Content-Type':'audio/wav'}})
 Object.defineProperty(response,'blob',{value:async()=>new Blob(['synthetic'],{type:'audio/wav'})})
 return response
}
beforeEach(()=>{
 requests.length=0;players.length=0
 localStorage.setItem('token','synthetic-isolated-token')
 vi.stubGlobal('Audio',class extends Player {constructor(){super();players.push(this)}})
 vi.spyOn(URL,'createObjectURL').mockReturnValue('blob:synthetic-playback')
 vi.spyOn(URL,'revokeObjectURL').mockImplementation(()=>{})
})
afterEach(()=>{app?.unmount();app=undefined;root?.remove();localStorage.clear();vi.restoreAllMocks();vi.unstubAllGlobals()})
function mount(fetcher: typeof fetch) {
 setupApiClient({baseUrl:'https://api.example.invalid/api',fetch:fetcher})
 const messages=ref<ChatMessage[]>([]),draft=ref('');let speech!: ReturnType<typeof useChatReadAloud>
 root=document.createElement('div');document.body.append(root)
 app=createApp(defineComponent({setup(){speech=useChatReadAloud({botId:ref(bot),scope:ref(bot+':original-session'),enabled:ref(true),loading:ref(false),draft,messages});return()=>h('div')}}));app.mount(root)
 return {messages,draft,speech}
}
describe('Harmony actual generated SDK read-aloud seam',()=>{
 it('uses the configured HTTPS API base/auth and binary playback endpoint; history is silent',async()=>{
  const fetcher=vi.fn(async (input: RequestInfo|URL)=>{requests.push(input as Request);return audioResponse()})
  const f=mount(fetcher);f.messages.value=[{...message(false),id:'history',turnId:'history-turn',runtimeRunId:'history-run'}];await tick();expect(requests).toHaveLength(0)
  f.messages.value=[message(true)];await tick();f.messages.value=[message(false)];await tick()
  expect(requests).toHaveLength(1);const request=requests[0]!
  expect(request.url).toBe(`https://api.example.invalid/api/bots/${bot}/tts/playback`)
  expect(request.headers.get('authorization')).toBe('Bearer synthetic-isolated-token');expect(request.method).toBe('POST')
  expect(await request.clone().json()).toEqual({text:'手机端合成验证'});expect(players).toHaveLength(1)
  players[0]!.dispatchEvent(new Event('playing'));expect(f.speech.status(f.messages.value[0]!)).toBe('playing')
  f.draft.value='输入';expect(players[0]!.src).toBe('');expect(f.speech.state.value.status).toBe('idle')
 })
 it.each([403,404])('keeps HTTP%s failure explicit and never falls back to synthesize or automatically retries',async status=>{
  const fetcher=vi.fn(async(input: RequestInfo|URL)=>{requests.push(input as Request);return new Response('{"code":"http.not_found"}',{status,headers:{'Content-Type':'application/problem+json'}})})
  const f=mount(fetcher);f.messages.value=[message(true)];await tick();f.messages.value=[message(false)];await tick()
  expect(f.speech.state.value.status).toBe('error');expect(players).toHaveLength(0)
  expect(requests).toHaveLength(1);expect(requests[0]!.url.endsWith('/tts/playback')).toBe(true)
  await tick();expect(fetcher).toHaveBeenCalledTimes(1);expect(requests.some(r=>r.url.includes('/synthesize'))).toBe(false)
 })
 it('aborts the actual fetch signal on interruption and discards a late binary response',async()=>{
  let finish!: (r:Response)=>void
  const fetcher=vi.fn((input: RequestInfo|URL)=>{requests.push(input as Request);return new Promise<Response>(resolve=>{finish=resolve})})
  const f=mount(fetcher);f.messages.value=[message(true)];await tick();f.messages.value=[message(false)];await tick();expect(requests).toHaveLength(1)
  f.speech.stop();expect(requests[0]!.signal.aborted).toBe(true);finish(audioResponse());await tick()
  expect(players).toHaveLength(0);expect(f.speech.state.value.status).toBe('idle');expect(fetcher).toHaveBeenCalledTimes(1)
 })
})

